        "display": true,
        "benches": [
          {
            "name": "Average buffered I/O file read bandwidth on Linux",
            "value": "10185.220152",
            "unit": "MB/s",
            "extra": "linux_result"
          },
          {
            "name": "Average buffered I/O file read bandwidth on Asterinas",
            "value": "9549.62168",
            "unit": "MB/s",
            "extra": "aster_result"
          }
        ]
